def check_min_pebbles(n):
    if n < 100:
        return "Fails: Cannot assign at least 1 pebble to 100 boxes."

    # Check the crucial condition: if any box has 1 pebble, Bob wins immediately.
    # We assume the worst initial distribution that fails the condition, e.g., (2^99, 1).
    if n < 200:
        # Since we must have 100 boxes, if n=199, at least one box must have 1 pebble.
        print(f"For n={n}, by Pigeonhole Principle, there must be at least one box with 1 pebble.")
        return "FAIL: Bob wins immediately if p_i=1."
    else:
        return "PASS: n >= 200 allows p_i >= 2."

print(check_min_pebbles(199))
print(check_min_pebbles(200))
